            "user_id": CTX.user_id|d,
            "roles_added": CTX.roles_to_add|d|join(', '),
            "date_added": CTX.date_added|d
        }
    )
-%}
{{- CTX.audit_log | flatten -}}

{%- do CTX.audit_log.append(
        {
            "message": "Discord User Found",
            "code": 200,
            "information": "Lookup for " ~ CTX.username ~ " found the User ID: " ~ CTX.user_id,
            "user_id": CTX.user_id,
            "date_joined" : CTX.date_joined,
            "user_info": CTX.user_info        }
    )
-%}
{{- CTX.audit_log -}}

{%- do CTX.audit_log.append(
        {
            "message": "Role Addition failed",
            "code": 500,
            "information": "Roles " ~ CTX.roles_to_add|d|join(', ') ~ " Failled adding to " ~ CTX.username|d ~ " (user id: " ~ CTX.user_id|d ~ ")",
            "user_id": CTX.user_id|d,
            "roles_failed": CTX.roles_to_add|d|join(', '),
            "date_failed": CTX.date_added|d
        }
    )
-%}
{{- CTX.audit_log | flatten -}}

{% set roles_to_add_id = [] %}
{% for role_to_add in CTX.roles_to_add %}
    {% for role in CTX.all_roles %}
        {% if role_to_add in [role.name,role.id] -%}
            {%- do roles_to_add_id.append(role.id) -%}
        {% endif %}
    {% endfor %}
{% endfor %}
{{- roles_to_add_id -}}

{% set roles_to_remove_id = [] %}
{% for role_to_remove in CTX.roles_to_remove %}
    {% for role in CTX.all_roles %}
        {% if role_to_remove in [role.name,role.id] %}
            {%- do roles_to_remove_id.append(role.id) -%}
        {% endif %}
    {% endfor %}
{% endfor %}
{{- roles_to_remove_id -}}

{%- do CTX.audit_log.append(
        {
            "message": "Role Removed",
            "code": 200,
            "information": "Roles " ~ CTX.roles_to_remove|d|join(', ') ~ " removed from " ~ CTX.username ~ " (user id: " ~ CTX.user_id ~ ")",
            "user_id": CTX.user_id|d,
            "roles_removed": CTX.roles_to_remove|d|join(', '),
            "date_removed": CTX.date_removed|d
        }
    )
-%}
{{- CTX.audit_log | flatten -}}

